cat > src/docs.go << 'EOF'
package main

import (
	"strings"
)

// rawDoc holds one input document with its original format label
type rawDoc struct {
	fmt  string
	data []byte
}

// splitDocs splits incoming bytes into zero or more documents
func splitDocs(data []byte, fmtName string) []rawDoc {
	if len(data) == 0 {
		return nil
	}
	switch fmtName {
	case "yaml", "kyaml":
		return splitYamlDocs(data)
	default:
		return []rawDoc{{fmt: fmtName, data: data}}
	}
}

func splitYamlDocs(data []byte) []rawDoc {
	s := string(data)
	lines := strings.Split(s, "\n")
	var docs []rawDoc
	var cur []string
	flush := func() {
		if len(cur) == 0 {
			return
		}
		joined := strings.Join(cur, "\n")
		if strings.TrimSpace(joined) == "" {
			cur = nil
			return
		}
		docs = append(docs, rawDoc{fmt: "yaml", data: []byte(joined)})
		cur = nil
	}
	for _, ln := range lines {
		t := strings.TrimSpace(ln)
		if t == "---" {
			flush()
			continue
		}
		cur = append(cur, ln)
	}
	flush()
	if len(docs) == 0 {
		return nil
	}
	return docs
}
EOF
echo "done"

