package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Value types mirror JSON + typed scalars for YAML round-trip
type ValKind int

const (
	VNull ValKind = iota
	VBool
	VInt
	VFloat
	VString
	VArray
	VObject
)

type Value struct {
	Kind    ValKind
	Bool    bool
	Int     int64
	Float   float64
	Str     string
	// Style hint for strings: "", "'", "\"", "|", ">"
	Style   string
	// Did the original source explicitly mark numeric form?
	Array   []*Value
	// Preserve insertion order
	ObjKeys []string
	ObjVals []*Value
	// Original scalar text (best-effort for YAML round-trip)
	Raw string
}

func NewNull() *Value             { return &Value{Kind: VNull} }
func NewBool(b bool) *Value       { return &Value{Kind: VBool, Bool: b} }
func NewInt(n int64) *Value       { return &Value{Kind: VInt, Int: n} }
func NewFloat(f float64) *Value   { return &Value{Kind: VFloat, Float: f} }
func NewString(s string) *Value   { return &Value{Kind: VString, Str: s} }
func NewArray() *Value            { return &Value{Kind: VArray} }
func NewObject() *Value           { return &Value{Kind: VObject} }

func (v *Value) Get(key string) (*Value, bool) {
	if v.Kind != VObject {
		return nil, false
	}
	for i, k := range v.ObjKeys {
		if k == key {
			return v.ObjVals[i], true
		}
	}
	return nil, false
}

func (v *Value) Set(key string, val *Value) {
	if v.Kind != VObject {
		v.Kind = VObject
		v.ObjKeys = nil
		v.ObjVals = nil
	}
	for i, k := range v.ObjKeys {
		if k == key {
			v.ObjVals[i] = val
			return
		}
	}
	v.ObjKeys = append(v.ObjKeys, key)
	v.ObjVals = append(v.ObjVals, val)
}

func (v *Value) Truthy() bool {
	switch v.Kind {
	case VNull:
		return false
	case VBool:
		return v.Bool
	case VInt:
		return v.Int != 0
	case VFloat:
		return v.Float != 0
	case VString:
		return v.Str != ""
	case VArray:
		return len(v.Array) > 0
	case VObject:
		return len(v.ObjKeys) > 0
	}
	return false
}

// Attempts to coerce a raw scalar string into a typed value using YAML 1.2 core schema.
func ParseScalar(s string) *Value {
	switch s {
	case "", "~", "null", "Null", "NULL":
		return NewNull()
	case "true", "True", "TRUE":
		return NewBool(true)
	case "false", "False", "FALSE":
		return NewBool(false)
	}
	if n, err := strconv.ParseInt(s, 10, 64); err == nil {
		return NewInt(n)
	}
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		if n, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return NewInt(n)
		}
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return NewFloat(f)
	}
	return NewString(s)
}

// DeepCopy returns a deep copy of the value.
func (v *Value) DeepCopy() *Value {
	if v == nil {
		return nil
	}
	cp := *v
	if v.Kind == VArray {
		cp.Array = make([]*Value, len(v.Array))
		for i, x := range v.Array {
			cp.Array[i] = x.DeepCopy()
		}
	}
	if v.Kind == VObject {
		cp.ObjKeys = append([]string(nil), v.ObjKeys...)
		cp.ObjVals = make([]*Value, len(v.ObjVals))
		for i, x := range v.ObjVals {
			cp.ObjVals[i] = x.DeepCopy()
		}
	}
	return &cp
}

// Human-readable helper for debugging.
func (v *Value) String() string {
	if v == nil {
		return "<nil>"
	}
	switch v.Kind {
	case VNull:
		return "null"
	case VBool:
		if v.Bool {
			return "true"
		}
		return "false"
	case VInt:
		return fmt.Sprintf("%d", v.Int)
	case VFloat:
		return strconv.FormatFloat(v.Float, 'g', -1, 64)
	case VString:
		return v.Str
	case VArray:
		return fmt.Sprintf("array(len=%d)", len(v.Array))
	case VObject:
		return fmt.Sprintf("object(len=%d)", len(v.ObjKeys))
	}
	return ""
}
EOF
echo "done"

