func writeJSONIndent(w io.Writer, v *Value, indent, depth int, topLevel bool) error {
	prefix := strings.Repeat(" ", indent*depth)
	childPrefix := strings.Repeat(" ", indent*(depth+1))
	switch v.Kind {
	case VNull:
		fmt.Fprint(w, "null")
	case VBool:
		if v.Bool {
