		}
	case VInt:
		fmt.Fprintf(w, "%d", v.Int)
	case VFloat:
		fmt.Fprint(w, formatFloat(v.Float))
	case VString:
		fmt.Fprint(w, encodeJSONString(v.Str))
	case VArray:
		if len(v.Array) == 0 {
			fmt.Fprint(w, "[]")
			return nil
		}
