					fmt.Fprint(w, ",")
				}
				if err := writeJSONIndent(w, el, 0, depth+1, false); err != nil {
					return err
				}
			}
			fmt.Fprint(w, "]")
		} else {
			fmt.Fprint(w, "[\n")
			for i, el := range v.Array {
