					return err
				}
				if i < len(v.Array)-1 {
					fmt.Fprint(w, ",")
				}
				fmt.Fprint(w, "\n")
			}
			fmt.Fprint(w, prefix, "]")
		}
	case VObject:
		if len(v.ObjKeys) == 0 {
			fmt.Fprint(w, "{}")
			return nil
		}
