				}
				fmt.Fprint(w, encodeJSONString(k), ":")
				if err := writeJSONIndent(w, v.ObjVals[i], 0, depth+1, false); err != nil {
					return err
				}
			}
			fmt.Fprint(w, "}")
		} else {
			fmt.Fprint(w, "{\n")
			for i, k := range v.ObjKeys {
