				if err := writeJSONIndent(w, v.ObjVals[i], indent, depth+1, false); err != nil {
					return err
				}
				if i < len(v.ObjKeys)-1 {
					fmt.Fprint(w, ",")
				}
				fmt.Fprint(w, "\n")
			}
			fmt.Fprint(w, prefix, "}")
		}
	}
	if topLevel {
		fmt.Fprintln(w)
	}
	return nil
}

func encodeJSONString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if r < 0x20 {
				fmt.Fprintf(&sb, "\\u%04x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

