package main

import (
	"fmt"
	"io"
	"strconv"
	"strings"
)

// ----- Minimal YAML parser for common block-style input -----

type yamlParser struct {
	lines []string
	pos   int
}

func parseYAML(data []byte) (*Value, error) {
	text := string(data)
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.TrimPrefix(text, "\ufeff")
	// Strip YAML directives and leading ---
	rawLines := strings.Split(text, "\n")
	var clean []string
	for _, ln := range rawLines {
		trim := strings.TrimSpace(ln)
		if strings.HasPrefix(trim, "%") {
			continue
		}
		if trim == "---" || trim == "..." {
			continue
		}
		clean = append(clean, ln)
	}
	// Remove comments (naive: drop everything after unquoted #)
	for i, ln := range clean {
		clean[i] = stripYamlComment(ln)
	}
	p := &yamlParser{lines: clean}
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return NewNull(), nil
	}
	// Detect if first non-blank line starts at column 0 with a flow scalar
	first := p.lines[p.pos]
	trim := strings.TrimSpace(first)
	if strings.HasPrefix(trim, "{") || strings.HasPrefix(trim, "[") {
		// entire doc is a flow value
		full := strings.Join(p.lines[p.pos:], "\n")
		v, _, err := parseFlowValue(full, 0)
		return v, err
	}
	// Check if it's a plain scalar-only doc (no mapping or sequence markers anywhere)
	looksLikeStructure := false
	for _, ln := range p.lines[p.pos:] {
		t := strings.TrimLeft(ln, " \t")
		if strings.HasPrefix(t, "- ") || t == "-" {
			looksLikeStructure = true
			break
		}
		if hasTopLevelColon(t) {
			looksLikeStructure = true
			break
		}
	}
	if !looksLikeStructure {
		allLines := strings.Join(p.lines[p.pos:], "\n")
		return ParseScalar(strings.TrimSpace(allLines)), nil
	}
	v, err := p.parseBlockNode(0)
	return v, err
}

func (p *yamlParser) skipBlank() {
	for p.pos < len(p.lines) {
		t := strings.TrimSpace(p.lines[p.pos])
		if t == "" {
			p.pos++
			continue
		}
		break
	}
}

func stripYamlComment(s string) string {
	inSingle := false
	inDouble := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if c == '"' && !inSingle {
			if i > 0 && s[i-1] == '\\' {
				continue
			}
			inDouble = !inDouble
			continue
		}
		if c == '#' && !inSingle && !inDouble {
			// must be preceded by whitespace or line start
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return s
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func hasTopLevelColon(s string) bool {
	inSingle := false
	inDouble := false
	flow := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if c == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if inSingle || inDouble {
			continue
		}
		if c == '{' || c == '[' {
			flow++
			continue
		}
		if c == '}' || c == ']' {
			flow--
			continue
		}
		if flow == 0 && c == ':' {
			// key if followed by space or end of line
			if i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\t' {
				return true
			}
		}
	}
	return false
}

func (p *yamlParser) parseBlockNode(indent int) (*Value, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return NewNull(), nil
	}
	line := p.lines[p.pos]
	ind := indentOf(line)
	if ind < indent {
		return NewNull(), nil
	}
	trim := strings.TrimLeft(line, " ")
	if strings.HasPrefix(trim, "- ") || trim == "-" {
		return p.parseSequence(ind)
	}
	if hasTopLevelColon(trim) {
		return p.parseMapping(ind)
	}
	// Plain scalar value (possibly folded later)
	p.pos++
	return ParseScalar(strings.TrimSpace(trim)), nil
}

func (p *yamlParser) parseSequence(indent int) (*Value, error) {
	arr := NewArray()
	for p.pos < len(p.lines) {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, fmt.Errorf("unexpected indent at line %d", p.pos+1)
		}
		trim := strings.TrimLeft(line, " ")
		if !strings.HasPrefix(trim, "-") {
			break
		}
		rest := trim[1:]
		if strings.HasPrefix(rest, " ") {
			rest = rest[1:]
		}
		if strings.TrimSpace(rest) == "" {
			p.pos++
			v, err := p.parseBlockNode(indent + 2)
			if err != nil {
				return nil, err
			}
			arr.Array = append(arr.Array, v)
			continue
		}
		// same-line item
		// Could be a mapping, sequence, flow, or scalar
		restTrim := strings.TrimSpace(rest)
		if strings.HasPrefix(restTrim, "{") || strings.HasPrefix(restTrim, "[") {
			v, _, err := parseFlowValue(restTrim, 0)
			if err != nil {
				return nil, err
			}
			p.pos++
			arr.Array = append(arr.Array, v)
			continue
		}
		if hasTopLevelColon(rest) {
			// rewrite the line so mapping parser can pick it up at indent+2
			newPrefix := strings.Repeat(" ", indent+2)
			p.lines[p.pos] = newPrefix + rest
			v, err := p.parseMapping(indent + 2)
			if err != nil {
				return nil, err
			}
			arr.Array = append(arr.Array, v)
			continue
		}
		// plain scalar
		arr.Array = append(arr.Array, ParseScalar(restTrim))
		p.pos++
	}
	return arr, nil
}

func (p *yamlParser) parseMapping(indent int) (*Value, error) {
	obj := NewObject()
	for p.pos < len(p.lines) {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		ind := indentOf(line)
		if ind < indent {
			break
		}
		if ind > indent {
			return nil, fmt.Errorf("unexpected indent at line %d", p.pos+1)
		}
		trim := strings.TrimLeft(line, " ")
		if strings.HasPrefix(trim, "- ") {
			break
		}
		if !hasTopLevelColon(trim) {
			break
		}
		key, rest := splitKeyValue(trim)
		p.pos++
		if rest == "" {
			// next line (deeper indent) is the value
			v, err := p.parseBlockNode(indent + 2)
			if err != nil {
				return nil, err
			}
			obj.Set(key, v)
			continue
		}
		restTrim := strings.TrimSpace(rest)
		if strings.HasPrefix(restTrim, "{") || strings.HasPrefix(restTrim, "[") {
			v, _, err := parseFlowValue(restTrim, 0)
			if err != nil {
				return nil, err
			}
			obj.Set(key, v)
			continue
		}
		// plain scalar (quoted strings supported minimally)
		obj.Set(key, parsePlainScalar(restTrim))
	}
	return obj, nil
}

func splitKeyValue(s string) (string, string) {
	inSingle, inDouble := false, false
	flow := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if c == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if inSingle || inDouble {
			continue
		}
		if c == '{' || c == '[' {
			flow++
			continue
		}
		if c == '}' || c == ']' {
			flow--
			continue
		}
		if flow == 0 && c == ':' {
			if i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\t' {
				key := strings.TrimSpace(s[:i])
				key = stripQuotes(key)
				rest := ""
				if i+1 < len(s) {
					rest = s[i+1:]
					rest = strings.TrimLeft(rest, " \t")
				}
				return key, rest
			}
		}
	}
	return s, ""
}

func stripQuotes(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func parsePlainScalar(s string) *Value {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return NewString(unescapeDouble(s[1 : len(s)-1]))
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return NewString(strings.ReplaceAll(s[1:len(s)-1], "''", "'"))
	}
	return ParseScalar(s)
}

func unescapeDouble(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			nxt := s[i+1]
			switch nxt {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			default:
				sb.WriteByte(nxt)
			}
			i++
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

// parseFlowValue parses a JSON-like flow scalar starting at the given string.
// Returns the Value, the number of characters consumed, and any error.
func parseFlowValue(s string, _ int) (*Value, int, error) {
	// Try to use JSON parser for flow values.
	// But YAML flow is not exactly JSON: keys can be unquoted.
	// Attempt JSON parse first; if that fails, fall back.
	v, err := parseJSON([]byte(s))
	if err == nil {
		return v, len(s), nil
	}
	// Very simple fallback for patterns like {a: 1, b: 2}
	v, n, err2 := parseFlowLoose(s)
	if err2 != nil {
		return nil, 0, err
	}
	return v, n, nil
}

func parseFlowLoose(s string) (*Value, int, error) {
	pos := 0
	skip := func() {
		for pos < len(s) && (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n') {
			pos++
		}
	}
	var parseNode func() (*Value, error)
	parseScalar := func() (*Value, error) {
		start := pos
		for pos < len(s) && s[pos] != ',' && s[pos] != '}' && s[pos] != ']' && s[pos] != ':' && s[pos] != '\n' {
			pos++
		}
		return ParseScalar(strings.TrimSpace(s[start:pos])), nil
	}
	parseNode = func() (*Value, error) {
		skip()
		if pos >= len(s) {
			return nil, fmt.Errorf("unexpected eof")
		}
		switch s[pos] {
		case '{':
			pos++
			obj := NewObject()
			for {
				skip()
				if pos < len(s) && s[pos] == '}' {
					pos++
					return obj, nil
				}
				keyStart := pos
				// Key may be quoted
				if pos < len(s) && (s[pos] == '"' || s[pos] == '\'') {
					q := s[pos]
					pos++
					for pos < len(s) && s[pos] != q {
						pos++
					}
					if pos < len(s) {
						pos++
					}
				} else {
					for pos < len(s) && s[pos] != ':' && s[pos] != ',' && s[pos] != '}' {
						pos++
					}
				}
				key := strings.TrimSpace(s[keyStart:pos])
				key = stripQuotes(key)
				skip()
				if pos < len(s) && s[pos] == ':' {
					pos++
				}
				val, err := parseNode()
				if err != nil {
					return nil, err
				}
				obj.Set(key, val)
				skip()
				if pos < len(s) && s[pos] == ',' {
					pos++
					continue
				}
				if pos < len(s) && s[pos] == '}' {
					pos++
					return obj, nil
				}
				return nil, fmt.Errorf("expected ',' or '}'")
			}
		case '[':
			pos++
			arr := NewArray()
			for {
				skip()
				if pos < len(s) && s[pos] == ']' {
					pos++
					return arr, nil
				}
				v, err := parseNode()
				if err != nil {
					return nil, err
				}
				arr.Array = append(arr.Array, v)
				skip()
				if pos < len(s) && s[pos] == ',' {
					pos++
					continue
				}
				if pos < len(s) && s[pos] == ']' {
					pos++
					return arr, nil
				}
				return nil, fmt.Errorf("expected ',' or ']'")
			}
		case '"', '\'':
			q := s[pos]
			pos++
			start := pos
			for pos < len(s) && s[pos] != q {
				pos++
			}
			val := s[start:pos]
			if pos < len(s) {
				pos++
			}
			return NewString(val), nil
		}
		return parseScalar()
	}
	v, err := parseNode()
	return v, pos, err
}

// ----- YAML writer (block style) -----

func writeYAML(w io.Writer, v *Value, opts *Options) error {
	if v == nil || v.Kind == VNull {
		fmt.Fprintln(w, "null")
		return nil
	}
	if isPrimitiveLike(v) {
		fmt.Fprintln(w, formatYamlScalar(v))
		return nil
	}
	return writeYAMLBlock(w, v, 0, opts)
}

func isPrimitiveLike(v *Value) bool {
	switch v.Kind {
	case VArray:
		return len(v.Array) == 0
	case VObject:
		return len(v.ObjKeys) == 0
	}
	return true
}

func writeYAMLBlock(w io.Writer, v *Value, depth int, opts *Options) error {
	prefix := strings.Repeat(" ", depth*opts.Indent)
	switch v.Kind {
	case VArray:
		if len(v.Array) == 0 {
			fmt.Fprintln(w, prefix+"[]")
			return nil
		}
		for _, el := range v.Array {
			if isScalar(el) {
				fmt.Fprintln(w, prefix+"- "+formatYamlScalar(el))
				continue
			}
			if el.Kind == VArray {
				if len(el.Array) == 0 {
					fmt.Fprintln(w, prefix+"- []")
					continue
				}
				fmt.Fprintln(w, prefix+"-")
				if err := writeYAMLBlock(w, el, depth+1, opts); err != nil {
					return err
				}
				continue
			}
			// object
			if len(el.ObjKeys) == 0 {
				fmt.Fprintln(w, prefix+"- {}")
				continue
			}
			for i, k := range el.ObjKeys {
				val := el.ObjVals[i]
				if i == 0 {
					fmt.Fprint(w, prefix+"- ")
				} else {
					fmt.Fprint(w, prefix+"  ")
				}
				if err := writeYamlKV(w, k, val, depth+1, opts); err != nil {
					return err
				}
			}
		}
	case VObject:
		if len(v.ObjKeys) == 0 {
			fmt.Fprintln(w, prefix+"{}")
			return nil
		}
		for i, k := range v.ObjKeys {
			val := v.ObjVals[i]
			fmt.Fprint(w, prefix)
			if err := writeYamlKV(w, k, val, depth, opts); err != nil {
				return err
			}
		}
	default:
		fmt.Fprintln(w, prefix+formatYamlScalar(v))
	}
	return nil
}

func writeYamlKV(w io.Writer, key string, val *Value, depth int, opts *Options) error {
	k := formatYamlKey(key)
	if isScalar(val) {
		fmt.Fprintln(w, k+": "+formatYamlScalar(val))
		return nil
	}
	switch val.Kind {
	case VArray:
		if len(val.Array) == 0 {
			fmt.Fprintln(w, k+": []")
			return nil
		}
		fmt.Fprintln(w, k+":")
		return writeYAMLBlock(w, val, depth+1, opts)
	case VObject:
		if len(val.ObjKeys) == 0 {
			fmt.Fprintln(w, k+": {}")
			return nil
		}
		fmt.Fprintln(w, k+":")
		return writeYAMLBlock(w, val, depth+1, opts)
	}
	fmt.Fprintln(w, k+": "+formatYamlScalar(val))
	return nil
}

func isScalar(v *Value) bool {
	switch v.Kind {
	case VArray, VObject:
		return false
	}
	return true
}

func formatYamlKey(s string) string {
	if keyNeedsQuoting(s) {
		return encodeJSONString(s)
	}
	return s
}

func keyNeedsQuoting(s string) bool {
	if s == "" {
		return true
	}
	first := s[0]
	if first == '"' || first == '\'' || first == '&' || first == '*' || first == '!' || first == '|' || first == '>' || first == '%' || first == '@' || first == '`' || first == '#' || first == ',' || first == '[' || first == ']' || first == '{' || first == '}' || first == '-' || first == '?' || first == ':' {
		return true
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == ':' || c == '#' {
			return true
		}
		if c < 0x20 {
			return true
		}
	}
	// Also quote if it parses as bool/null/number
	switch s {
	case "true", "false", "null", "True", "False", "Null", "TRUE", "FALSE", "NULL", "~":
		return true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return true
	}
	return false
}

func formatYamlScalar(v *Value) string {
	switch v.Kind {
	case VNull:
		return "null"
	case VBool:
		if v.Bool {
			return "true"
		}
		return "false"
	case VInt:
		return strconv.FormatInt(v.Int, 10)
	case VFloat:
		return formatFloat(v.Float)
	case VString:
		return formatYamlString(v.Str)
	}
	return ""
}

func formatYamlString(s string) string {
	if s == "" {
		return `""`
	}
	if stringNeedsQuoting(s) {
		return encodeJSONString(s)
	}
	return s
}

func stringNeedsQuoting(s string) bool {
	if s == "" {
		return true
	}
	// Check special values
	switch s {
	case "true", "false", "null", "True", "False", "Null", "TRUE", "FALSE", "NULL", "~":
		return true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return true
	}
	if _, err := strconv.ParseInt(s, 10, 64); err == nil {
		return true
	}
	// Special chars
	first := s[0]
	if first == ' ' || first == '\t' {
		return true
	}
	switch first {
	case '"', '\'', '&', '*', '!', '|', '>', '%', '@', '`', '#', ',', '[', ']', '{', '}', '-', '?', ':':
		return true
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\t' {
			return true
		}
		if c == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
			return true
		}
		if c == ':' && (i+1 == len(s) || s[i+1] == ' ') {
			return true
		}
		if c < 0x20 {
			return true
		}
	}
	return false
}
