			}
			obj.Set(key, v)
			continue
		}
		restTrim := strings.TrimSpace(rest)
		if strings.HasPrefix(restTrim, "{") || strings.HasPrefix(restTrim, "[") {
			v, _, err := parseFlowValue(restTrim, 0)
			if err != nil {
				return nil, err
			}
			obj.Set(key, v)
			continue
		}
		// plain scalar (quoted strings supported minimally)
		obj.Set(key, parsePlainScalar(restTrim))
	}
