package main

import (
	"fmt"
	"strconv"
	"strings"
)

// ----- Expression evaluator (minimal subset of yq) -----

// Token types
type tokKind int

const (
	tkEOF tokKind = iota
	tkDot
	tkIdent
	tkLBrack
	tkRBrack
	tkLParen
	tkRParen
	tkLBrace
	tkRBrace
	tkNumber
	tkString
	tkEq
	tkPipe
	tkComma
	tkColon
	tkQuestion
)

type token struct {
	kind tokKind
	text string
	pos  int
}

type lexer struct {
	s    string
	pos  int
}

func (l *lexer) next() (token, error) {
	for l.pos < len(l.s) {
		c := l.s[l.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			l.pos++
			continue
		}
		break
	}
	if l.pos >= len(l.s) {
		return token{kind: tkEOF, pos: l.pos}, nil
	}
	start := l.pos
	c := l.s[l.pos]
	switch c {
	case '.':
		l.pos++
		return token{kind: tkDot, text: ".", pos: start}, nil
	case '[':
		l.pos++
		return token{kind: tkLBrack, text: "[", pos: start}, nil
	case ']':
		l.pos++
		return token{kind: tkRBrack, text: "]", pos: start}, nil
	case '(':
		l.pos++
		return token{kind: tkLParen, text: "(", pos: start}, nil
	case ')':
		l.pos++
		return token{kind: tkRParen, text: ")", pos: start}, nil
	case '{':
		l.pos++
		return token{kind: tkLBrace, text: "{", pos: start}, nil
	case '}':
		l.pos++
		return token{kind: tkRBrace, text: "}", pos: start}, nil
	case '=':
		l.pos++
		return token{kind: tkEq, text: "=", pos: start}, nil
	case '|':
		l.pos++
		return token{kind: tkPipe, text: "|", pos: start}, nil
	case ',':
		l.pos++
		return token{kind: tkComma, text: ",", pos: start}, nil
	case ':':
		l.pos++
		return token{kind: tkColon, text: ":", pos: start}, nil
	case '?':
		l.pos++
		return token{kind: tkQuestion, text: "?", pos: start}, nil
	case '"':
		// string literal
		l.pos++
		var sb strings.Builder
		for l.pos < len(l.s) && l.s[l.pos] != '"' {
			if l.s[l.pos] == '\\' && l.pos+1 < len(l.s) {
				nxt := l.s[l.pos+1]
				switch nxt {
				case 'n':
					sb.WriteByte('\n')
				case 't':
					sb.WriteByte('\t')
				case 'r':
					sb.WriteByte('\r')
				case '"':
					sb.WriteByte('"')
				case '\\':
					sb.WriteByte('\\')
				default:
					sb.WriteByte(nxt)
				}
				l.pos += 2
				continue
			}
			sb.WriteByte(l.s[l.pos])
			l.pos++
		}
		if l.pos < len(l.s) {
			l.pos++
		}
		return token{kind: tkString, text: sb.String(), pos: start}, nil
	}
	// Number
	if c == '-' || (c >= '0' && c <= '9') {
		start := l.pos
		if c == '-' {
			l.pos++
		}
		for l.pos < len(l.s) {
			cc := l.s[l.pos]
			if (cc >= '0' && cc <= '9') || cc == '.' || cc == 'e' || cc == 'E' {
				l.pos++
				continue
			}
			break
		}
		return token{kind: tkNumber, text: l.s[start:l.pos], pos: start}, nil
	}
	// Identifier
	if isIdentStart(c) {
		start := l.pos
		for l.pos < len(l.s) && isIdentChar(l.s[l.pos]) {
			l.pos++
		}
		return token{kind: tkIdent, text: l.s[start:l.pos], pos: start}, nil
	}
	return token{}, fmt.Errorf("1:%d: lexer: invalid input text %q", start+1, string(c))
}

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '$'
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}

// Expression AST
type Expr interface {
	apply(v *Value, opts *Options) ([]*Value, error)
}

// Path step: field or index
type pathStep struct {
	field string
	index int
	isIdx bool
	isAll bool // [] - iterate all
}

type pathExpr struct {
	steps []pathStep
}

func (e *pathExpr) apply(v *Value, _ *Options) ([]*Value, error) {
	cur := []*Value{v}
	for _, st := range e.steps {
		var next []*Value
		for _, x := range cur {
			if st.isAll {
				if x.Kind == VArray {
					for _, el := range x.Array {
						next = append(next, el)
					}
				} else if x.Kind == VObject {
					for _, val := range x.ObjVals {
						next = append(next, val)
					}
				}
				continue
			}
			if st.isIdx {
				if x.Kind == VArray {
					idx := st.index
					if idx < 0 {
						idx += len(x.Array)
					}
					if idx >= 0 && idx < len(x.Array) {
						next = append(next, x.Array[idx])
					} else {
						next = append(next, NewNull())
					}
				} else {
					next = append(next, NewNull())
				}
			} else {
				if x.Kind == VObject {
					if c, ok := x.Get(st.field); ok {
						next = append(next, c)
					} else {
						next = append(next, NewNull())
					}
				} else {
					next = append(next, NewNull())
				}
			}
		}
		cur = next
	}
	return cur, nil
}

type literalExpr struct {
	v *Value
}

func (e *literalExpr) apply(_ *Value, _ *Options) ([]*Value, error) {
	return []*Value{e.v.DeepCopy()}, nil
}

type pipeExpr struct {
	lhs, rhs Expr
}

func (e *pipeExpr) apply(v *Value, opts *Options) ([]*Value, error) {
	lvs, err := e.lhs.apply(v, opts)
	if err != nil {
		return nil, err
	}
	var out []*Value
	for _, lv := range lvs {
		rs, err := e.rhs.apply(lv, opts)
		if err != nil {
			return nil, err
		}
		out = append(out, rs...)
	}
	return out, nil
}

// Assign expression: applies to the root document
type assignExpr struct {
	path *pathExpr
	rhs  Expr
}

func (e *assignExpr) apply(v *Value, opts *Options) ([]*Value, error) {
	if v == nil || v.Kind == VNull {
		v = NewObject()
	}
	rs, err := e.rhs.apply(v, opts)
	if err != nil {
		return nil, err
	}
	if len(rs) == 0 {
		return []*Value{v}, nil
	}
	val := rs[0]
	root := v
	assignPath(&root, e.path.steps, val)
	return []*Value{root}, nil
}

func assignPath(root **Value, steps []pathStep, val *Value) {
	if len(steps) == 0 {
		*root = val
		return
	}
	cur := *root
	for i, st := range steps {
		last := i == len(steps)-1
		if st.isAll {
			// not supported deeply here
			return
		}
		if st.isIdx {
			if cur == nil || cur.Kind != VArray {
				na := NewArray()
				if cur != nil {
					*cur = *na
				} else {
					cur = na
					*root = cur
				}
				cur.Kind = VArray
			}
			// extend
			for len(cur.Array) <= st.index {
				cur.Array = append(cur.Array, NewNull())
			}
			if last {
				cur.Array[st.index] = val
				return
			}
			cur = cur.Array[st.index]
			continue
		}
		if cur == nil || cur.Kind != VObject {
			// mutate in place
			if cur != nil {
				cur.Kind = VObject
				cur.ObjKeys = nil
				cur.ObjVals = nil
			} else {
				cur = NewObject()
				*root = cur
			}
		}
		child, ok := cur.Get(st.field)
		if !ok {
			// create appropriate child
			if last {
				cur.Set(st.field, val)
				return
			}
			// peek next step to decide container
			var fresh *Value
			if steps[i+1].isIdx {
				fresh = NewArray()
			} else {
				fresh = NewObject()
			}
			cur.Set(st.field, fresh)
			cur = fresh
			continue
		}
		if last {
			// replace
			for idx, k := range cur.ObjKeys {
				if k == st.field {
					cur.ObjVals[idx] = val
					return
				}
			}
		}
		cur = child
	}
}

// Parser
type parser struct {
	toks []token
	pos  int
}

func parseExpr(src string) (Expr, error) {
	l := &lexer{s: src}
	var toks []token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		toks = append(toks, t)
		if t.kind == tkEOF {
			break
		}
	}
	p := &parser{toks: toks}
	e, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tkEOF {
		return nil, fmt.Errorf("unexpected token %q", p.peek().text)
	}
	return e, nil
}

func (p *parser) peek() token {
	if p.pos >= len(p.toks) {
		return token{kind: tkEOF}
	}
	return p.toks[p.pos]
}
func (p *parser) take() token {
	t := p.peek()
	p.pos++
	return t
}

func (p *parser) parsePipe() (Expr, error) {
	lhs, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkPipe {
		p.take()
		rhs, err := p.parseAssign()
		if err != nil {
			return nil, err
		}
		lhs = &pipeExpr{lhs: lhs, rhs: rhs}
	}
	return lhs, nil
}

func (p *parser) parseAssign() (Expr, error) {
	lhs, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tkEq {
		p.take()
		pe, ok := lhs.(*pathExpr)
		if !ok {
			return nil, fmt.Errorf("left side of '=' must be a path")
		}
		rhs, err := p.parsePrimary()
		if err != nil {
			return nil, err
		}
		return &assignExpr{path: pe, rhs: rhs}, nil
	}
	return lhs, nil
}

func (p *parser) parsePrimary() (Expr, error) {
	t := p.peek()
	switch t.kind {
	case tkDot, tkIdent, tkLBrack:
		return p.parsePath()
	case tkString:
		p.take()
		return &literalExpr{v: NewString(t.text)}, nil
	case tkNumber:
		p.take()
		if strings.ContainsAny(t.text, ".eE") {
			f, err := strconv.ParseFloat(t.text, 64)
			if err != nil {
				return nil, err
			}
			return &literalExpr{v: NewFloat(f)}, nil
		}
		n, err := strconv.ParseInt(t.text, 10, 64)
		if err != nil {
			return nil, err
		}
		return &literalExpr{v: NewInt(n)}, nil
	case tkLParen:
		p.take()
		e, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if p.take().kind != tkRParen {
			return nil, fmt.Errorf("expected ')'")
		}
		return e, nil
	}
	return nil, fmt.Errorf("1:%d: lexer: invalid input text %q", t.pos+1, t.text)
}

func (p *parser) parsePath() (Expr, error) {
	pe := &pathExpr{}
	// Can start with . or directly an identifier
	for {
		t := p.peek()
		if t.kind == tkDot {
			p.take()
			// after '.', might be identifier or '['
			nxt := p.peek()
			if nxt.kind == tkIdent {
				p.take()
				pe.steps = append(pe.steps, pathStep{field: nxt.text})
				continue
			}
			if nxt.kind == tkLBrack {
				// handle below in the main loop
				continue
			}
			// standalone '.'
			break
		}
		if t.kind == tkIdent {
			p.take()
			pe.steps = append(pe.steps, pathStep{field: t.text})
			continue
		}
		if t.kind == tkLBrack {
			p.take()
			nxt := p.peek()
			if nxt.kind == tkRBrack {
				p.take()
				pe.steps = append(pe.steps, pathStep{isAll: true})
				continue
			}
			if nxt.kind == tkNumber {
				p.take()
				n, _ := strconv.Atoi(nxt.text)
				if p.take().kind != tkRBrack {
					return nil, fmt.Errorf("expected ']'")
				}
				pe.steps = append(pe.steps, pathStep{isIdx: true, index: n})
				continue
			}
			if nxt.kind == tkString {
				p.take()
				if p.take().kind != tkRBrack {
					return nil, fmt.Errorf("expected ']'")
				}
				pe.steps = append(pe.steps, pathStep{field: nxt.text})
				continue
			}
			return nil, fmt.Errorf("unexpected token in index: %q", nxt.text)
		}
		break
	}
	return pe, nil
}

// ----- Evaluate entry point -----

func evaluate(exprSrc string, doc rawDoc, opts *Options) (*Value, error) {
	var root *Value
	var err error
	switch doc.fmt {
	case "null":
		root = NewNull()
	case "json":
		root, err = parseJSON(doc.data)
	case "yaml", "kyaml":
		root, err = parseYAML(doc.data)
