	for i, st := range steps {
		last := i == len(steps)-1
		if st.isAll {
			// not supported deeply here
			return
		}
		if st.isIdx {
			if cur == nil || cur.Kind != VArray {
				na := NewArray()
				if cur != nil {
					*cur = *na
				} else {
					cur = na
					*root = cur
				}
				cur.Kind = VArray
			}
			// extend
			for len(cur.Array) <= st.index {
				cur.Array = append(cur.Array, NewNull())
			}
			if last {
				cur.Array[st.index] = val
				return
			}
			cur = cur.Array[st.index]
			continue
		}
		if cur == nil || cur.Kind != VObject {
			// mutate in place
			if cur != nil {
				cur.Kind = VObject
				cur.ObjKeys = nil
				cur.ObjVals = nil
			} else {
				cur = NewObject()
				*root = cur
			}
		}
		child, ok := cur.Get(st.field)
		if !ok {
			// create appropriate child
			if last {
				cur.Set(st.field, val)
				return
			}
			// peek next step to decide container
			var fresh *Value
			if steps[i+1].isIdx {
				fresh = NewArray()
			} else {
				fresh = NewObject()
			}
			cur.Set(st.field, fresh)
			cur = fresh
			continue
		}
		if last {
			// replace
			for idx, k := range cur.ObjKeys {
				if k == st.field {
					cur.ObjVals[idx] = val
					return
				}
			}
		}
		cur = child
	}
