		return
	}
	cur := *root
	for i, st := range steps {
		last := i == len(steps)-1
		if st.isAll {
			// not supported deeply here
			return
		}
		if st.isIdx {
			if cur == nil || cur.Kind != VArray {
				na := NewArray()
				if cur != nil {
					*cur = *na
				} else {
					cur = na
					*root = cur
				}
				cur.Kind = VArray
			}
			// extend
			for len(cur.Array) <= st.index {
				cur.Array = append(cur.Array, NewNull())
			}
			if last {
				cur.Array[st.index] = val
				return
			}
			cur = cur.Array[st.index]
			continue
		}
		if cur == nil || cur.Kind != VObject {
			// mutate in place
			if cur != nil {
				cur.Kind = VObject
				cur.ObjKeys = nil
				cur.ObjVals = nil
			} else {
				cur = NewObject()
				*root = cur
			}
		}
		child, ok := cur.Get(st.field)
		if !ok {
			// create appropriate child
			if last {
				cur.Set(st.field, val)
				return
			}
			// peek next step to decide container
			var fresh *Value
			if steps[i+1].isIdx {
				fresh = NewArray()
			} else {
				fresh = NewObject()
			}
			cur.Set(st.field, fresh)
			cur = fresh
			continue
		}
		if last {
			// replace
			for idx, k := range cur.ObjKeys {
				if k == st.field {
					cur.ObjVals[idx] = val
					return
				}
			}
		}
		cur = child
	}
}

// Parser
type parser struct {
	toks []token
	pos  int
}

func parseExpr(src string) (Expr, error) {
	l := &lexer{s: src}
	var toks []token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		toks = append(toks, t)
		if t.kind == tkEOF {
			break
		}
	}
	p := &parser{toks: toks}
	e, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tkEOF {
		return nil, fmt.Errorf("unexpected token %q", p.peek().text)
	}
	return e, nil
}

func (p *parser) peek() token {
	if p.pos >= len(p.toks) {
		return token{kind: tkEOF}
	}
	return p.toks[p.pos]
}
func (p *parser) take() token {
	t := p.peek()
	p.pos++
	return t
}

func (p *parser) parsePipe() (Expr, error) {
	lhs, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkPipe {
		p.take()
		rhs, err := p.parseAssign()
		if err != nil {
			return nil, err
		}
		lhs = &pipeExpr{lhs: lhs, rhs: rhs}
	}
	return lhs, nil
}

func (p *parser) parseAssign() (Expr, error) {
	lhs, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tkEq {
		p.take()
		pe, ok := lhs.(*pathExpr)
		if !ok {
			return nil, fmt.Errorf("left side of '=' must be a path")
		}
		rhs, err := p.parsePrimary()
		if err != nil {
			return nil, err
		}
		return &assignExpr{path: pe, rhs: rhs}, nil
	}
	return lhs, nil
}

func (p *parser) parsePrimary() (Expr, error) {
	t := p.peek()
	switch t.kind {
	case tkDot, tkIdent, tkLBrack:
		return p.parsePath()
	case tkString:
		p.take()
		return &literalExpr{v: NewString(t.text)}, nil
	case tkNumber:
		p.take()
		if strings.ContainsAny(t.text, ".eE") {
			f, err := strconv.ParseFloat(t.text, 64)
			if err != nil {
				return nil, err
			}
			return &literalExpr{v: NewFloat(f)}, nil
		}
		n, err := strconv.ParseInt(t.text, 10, 64)
		if err != nil {
			return nil, err
		}
		return &literalExpr{v: NewInt(n)}, nil
	case tkLParen:
		p.take()
		e, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if p.take().kind != tkRParen {
			return nil, fmt.Errorf("expected ')'")
		}
		return e, nil
	}
	return nil, fmt.Errorf("1:%d: lexer: invalid input text %q", t.pos+1, t.text)
}

func (p *parser) parsePath() (Expr, error) {
	pe := &pathExpr{}
	// Can start with . or directly an identifier
	for {
		t := p.peek()
		if t.kind == tkDot {
			p.take()
			// after '.', might be identifier or '['
			nxt := p.peek()
			if nxt.kind == tkIdent {
				p.take()
				pe.steps = append(pe.steps, pathStep{field: nxt.text})
				continue
			}
			if nxt.kind == tkLBrack {
				// handle below in the main loop
				continue
			}
			// standalone '.'
			break
		}
		if t.kind == tkIdent {
			p.take()
			pe.steps = append(pe.steps, pathStep{field: t.text})
			continue
		}
		if t.kind == tkLBrack {
			p.take()
			nxt := p.peek()
			if nxt.kind == tkRBrack {
				p.take()
				pe.steps = append(pe.steps, pathStep{isAll: true})
				continue
			}
			if nxt.kind == tkNumber {
				p.take()
				n, _ := strconv.Atoi(nxt.text)
				if p.take().kind != tkRBrack {
					return nil, fmt.Errorf("expected ']'")
				}
				pe.steps = append(pe.steps, pathStep{isIdx: true, index: n})
				continue
			}
			if nxt.kind == tkString {
				p.take()
				if p.take().kind != tkRBrack {
					return nil, fmt.Errorf("expected ']'")
				}
				pe.steps = append(pe.steps, pathStep{field: nxt.text})
				continue
			}
			return nil, fmt.Errorf("unexpected token in index: %q", nxt.text)
		}
		break
	}
	return pe, nil
}

// ----- Evaluate entry point -----

func evaluate(exprSrc string, doc rawDoc, opts *Options) (*Value, error) {
	var root *Value
	var err error
	switch doc.fmt {
	case "null":
		root = NewNull()
	case "json":
		root, err = parseJSON(doc.data)
	case "yaml", "kyaml":
		root, err = parseYAML(doc.data)
	default:
		// Attempt YAML first, then JSON
		root, err = parseYAML(doc.data)
		if err != nil {
			root, err = parseJSON(doc.data)
		}
	}
	if err != nil {
		return nil, err
	}
	exprSrc = strings.TrimSpace(exprSrc)
	if exprSrc == "" || exprSrc == "." {
		return root, nil
	}
	ex, err := parseExpr(exprSrc)
	if err != nil {
		return nil, err
	}
	results, err := ex.apply(root, opts)
	if err != nil {
		return nil, err
	}
	if len(results) == 0 {
		return NewNull(), nil
	}
	return results[0], nil
}
