// ----- Expression evaluator (minimal subset of yq) -----

// Token types
type tokKind int

const (
	tkEOF tokKind = iota
	tkDot
	tkIdent
	tkLBrack
	tkRBrack
	tkLParen
	tkRParen
	tkLBrace
	tkRBrace
	tkNumber
	tkString
	tkEq
	tkPipe
	tkComma
	tkColon
	tkQuestion
)

type token struct {
	kind tokKind
	text string
	pos  int
}

type lexer struct {
	s    string
	pos  int
}

func (l *lexer) next() (token, error) {
	for l.pos < len(l.s) {
		c := l.s[l.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			l.pos++
			continue
		}
		break
	}
	if l.pos >= len(l.s) {
		return token{kind: tkEOF, pos: l.pos}, nil
	}
	start := l.pos
	c := l.s[l.pos]
	switch c {
	case '.':
		l.pos++
		return token{kind: tkDot, text: ".", pos: start}, nil
	case '[':
		l.pos++
		return token{kind: tkLBrack, text: "[", pos: start}, nil
	case ']':
		l.pos++
		return token{kind: tkRBrack, text: "]", pos: start}, nil
	case '(':
		l.pos++
		return token{kind: tkLParen, text: "(", pos: start}, nil
	case ')':
		l.pos++
		return token{kind: tkRParen, text: ")", pos: start}, nil
	case '{':
		l.pos++
		return token{kind: tkLBrace, text: "{", pos: start}, nil
	case '}':
		l.pos++
		return token{kind: tkRBrace, text: "}", pos: start}, nil
	case '=':
		l.pos++
		return token{kind: tkEq, text: "=", pos: start}, nil
	case '|':
		l.pos++
		return token{kind: tkPipe, text: "|", pos: start}, nil
	case ',':
		l.pos++
		return token{kind: tkComma, text: ",", pos: start}, nil
	case ':':
		l.pos++
		return token{kind: tkColon, text: ":", pos: start}, nil
	case '?':
		l.pos++
		return token{kind: tkQuestion, text: "?", pos: start}, nil
	case '"':
		// string literal
		l.pos++
		var sb strings.Builder
		for l.pos < len(l.s) && l.s[l.pos] != '"' {
			if l.s[l.pos] == '\\' && l.pos+1 < len(l.s) {
				nxt := l.s[l.pos+1]
				switch nxt {
				case 'n':
					sb.WriteByte('\n')
				case 't':
					sb.WriteByte('\t')
				case 'r':
					sb.WriteByte('\r')
				case '"':
					sb.WriteByte('"')
				case '\\':
					sb.WriteByte('\\')
				default:
					sb.WriteByte(nxt)
				}
				l.pos += 2
				continue
			}
			sb.WriteByte(l.s[l.pos])
			l.pos++
		}
		if l.pos < len(l.s) {
			l.pos++
		}
		return token{kind: tkString, text: sb.String(), pos: start}, nil
	}
	// Number
	if c == '-' || (c >= '0' && c <= '9') {
		start := l.pos
		if c == '-' {
			l.pos++
		}
		for l.pos < len(l.s) {
			cc := l.s[l.pos]
			if (cc >= '0' && cc <= '9') || cc == '.' || cc == 'e' || cc == 'E' {
				l.pos++
				continue
			}
			break
		}
		return token{kind: tkNumber, text: l.s[start:l.pos], pos: start}, nil
	}
	// Identifier
	if isIdentStart(c) {
		start := l.pos
		for l.pos < len(l.s) && isIdentChar(l.s[l.pos]) {
			l.pos++
		}
		return token{kind: tkIdent, text: l.s[start:l.pos], pos: start}, nil
	}
	return token{}, fmt.Errorf("1:%d: lexer: invalid input text %q", start+1, string(c))
}

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '$'
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}

// Expression AST
type Expr interface {
	apply(v *Value, opts *Options) ([]*Value, error)
}

// Path step: field or index
type pathStep struct {
	field string
	index int
	isIdx bool
	isAll bool // [] - iterate all
}

type pathExpr struct {
	steps []pathStep
}

func (e *pathExpr) apply(v *Value, _ *Options) ([]*Value, error) {
	cur := []*Value{v}
	for _, st := range e.steps {
		var next []*Value
		for _, x := range cur {
			if st.isAll {
				if x.Kind == VArray {
					for _, el := range x.Array {
						next = append(next, el)
					}
				} else if x.Kind == VObject {
					for _, val := range x.ObjVals {
						next = append(next, val)
					}
				}
				continue
			}
			if st.isIdx {
				if x.Kind == VArray {
					idx := st.index
					if idx < 0 {
						idx += len(x.Array)
					}
					if idx >= 0 && idx < len(x.Array) {
						next = append(next, x.Array[idx])
					} else {
						next = append(next, NewNull())
					}
				} else {
					next = append(next, NewNull())
				}
			} else {
				if x.Kind == VObject {
					if c, ok := x.Get(st.field); ok {
						next = append(next, c)
					} else {
						next = append(next, NewNull())
					}
				} else {
					next = append(next, NewNull())
				}
			}
		}
		cur = next
	}
	return cur, nil
}

type literalExpr struct {
	v *Value
}

func (e *literalExpr) apply(_ *Value, _ *Options) ([]*Value, error) {
	return []*Value{e.v.DeepCopy()}, nil
}

type pipeExpr struct {
	lhs, rhs Expr
}

func (e *pipeExpr) apply(v *Value, opts *Options) ([]*Value, error) {
	lvs, err := e.lhs.apply(v, opts)
	if err != nil {
		return nil, err
	}
	var out []*Value
	for _, lv := range lvs {
		rs, err := e.rhs.apply(lv, opts)
		if err != nil {
			return nil, err
		}
		out = append(out, rs...)
	}
	return out, nil
}

// Assign expression: applies to the root document
type assignExpr struct {
	path *pathExpr
