	rs, err := e.rhs.apply(v, opts)
	if err != nil {
		return nil, err
	}
	if len(rs) == 0 {
		return []*Value{v}, nil
	}
	val := rs[0]
	root := v
	assignPath(&root, e.path.steps, val)
	return []*Value{root}, nil
}

