	case "yaml", "auto", "":
		return writeYAML(w, v, opts)
	case "props":
		return writeProps(w, v, opts)
	case "shell":
		return writeShell(w, v, opts)
	case "csv":
		return writeCSV(w, v, ",")
	case "tsv":
		return writeCSV(w, v, "\t")
	case "toml":
		return writeTOML(w, v, opts)
	case "xml":
		return writeXML(w, v, opts)
	case "lua":
		return writeLua(w, v, opts)
	case "ini":
		return writeINI(w, v, opts)
	case "base64":
		return writeBase64(w, v)
	case "uri":
		return writeURI(w, v)
	case "hcl":
		return writeHCL(w, v, opts)
	case "kyaml":
		return writeYAML(w, v, opts)
	}
	return fmt.Errorf("unsupported output format: %s", fmtName)
