	}
	return nil
}

func walkProps(v *Value, path string, opts *Options, out *[]string) {
	switch v.Kind {
	case VObject:
		for i, k := range v.ObjKeys {
			np := k
			if path != "" {
				np = path + "." + k
			}
			walkProps(v.ObjVals[i], np, opts, out)
		}
	case VArray:
		for i, el := range v.Array {
			var np string
			if opts.PropsArrayBrackets {
				if path == "" {
					np = "[" + strconv.Itoa(i) + "]"
				} else {
					np = path + "[" + strconv.Itoa(i) + "]"
				}
			} else {
				if path == "" {
					np = strconv.Itoa(i)
				} else {
					np = path + "." + strconv.Itoa(i)
				}
			}
			walkProps(el, np, opts, out)
		}
