func shellNeedsQuoting(s string) bool {
	for _, r := range s {
		if r == ' ' || r == '\t' || r == '\n' || r == '"' || r == '\'' || r == '$' || r == '`' || r == '\\' || r == '#' || r == '&' || r == '|' || r == ';' || r == '*' || r == '?' || r == '<' || r == '>' || r == '(' || r == ')' {
