	case VString:
		return "\"" + strings.ReplaceAll(v.Str, "\"", "\\\"") + "\""
	case VArray:
		parts := make([]string, len(v.Array))
		for i, e := range v.Array {
			parts[i] = hclScalar(e)
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	return scalarToText(v)
}
