func sBool(get func(*Options) *bool) func(string, *Options) error {
	return func(val string, o *Options) error {
		p := get(o)
		if val == "" {
			*p = true
			return nil
		}
		switch strings.ToLower(val) {
		case "true", "1", "t":
			*p = true
		case "false", "0", "f":
			*p = false
		default:
			return fmt.Errorf("invalid bool %q", val)
		}
		return nil
	}
}
func sStr(get func(*Options) *string) func(string, *Options) error {
	return func(val string, o *Options) error { *get(o) = val; return nil }
}
func sInt(get func(*Options) *int) func(string, *Options) error {
	return func(val string, o *Options) error {
		var n int
		_, err := fmt.Sscanf(val, "%d", &n)
		if err != nil {
			return err
		}
		*get(o) = n
		return nil
	}
}

// flag lookup utilities
func findLongFlag(name string) *flagDef {
	for i := range allFlags {
		if allFlags[i].long == name {
			return &allFlags[i]
		}
	}
	return nil
}
func findShortFlag(name string) *flagDef {
	for i := range allFlags {
		if allFlags[i].short == name {
			return &allFlags[i]
		}
	}
	return nil
}

// ---- help rendering ----

// Render a single flag line with description starting at column `descCol`.
func renderFlagLine(fd flagDef, descCol int) string {
	var nameSB strings.Builder
	if fd.short != "" {
		nameSB.WriteString("  -")
		nameSB.WriteString(fd.short)
		nameSB.WriteString(", --")
	} else {
		nameSB.WriteString("      --")
	}
	nameSB.WriteString(fd.long)
	if fd.argType != "" {
		nameSB.WriteByte(' ')
		nameSB.WriteString(fd.argType)
	}
	name := nameSB.String()
	pad := descCol - len(name)
	if pad < 3 {
		pad = 3
	}
	return name + strings.Repeat(" ", pad) + fd.desc
}

// buildFlagsList returns the formatted flag block, including optional help/version lines at proper positions.
func buildFlagsList(includeHelpVersion bool) string {
	type entry struct{ fd flagDef }
	// Create entries with alphabetical ordering by long name
	var entries []flagDef
	entries = append(entries, allFlags...)
	if includeHelpVersion {
		entries = append(entries, flagDef{short: "h", long: "help", desc: "help for yq"})
		entries = append(entries, flagDef{short: "V", long: "version", desc: "Print version information and quit"})
	}
	// Sort by long name (stable alphabetical)
	sortFlagsByLong(entries)
	descCol := 42
	var lines []string
	for _, fd := range entries {
		lines = append(lines, renderFlagLine(fd, descCol))
	}
	return strings.Join(lines, "\n")
}

func sortFlagsByLong(list []flagDef) {
	// Insertion sort (small list)
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && list[j].long < list[j-1].long; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
}

func rootHelp() string {
	var sb strings.Builder
	sb.WriteString(rootDescHeader)
	sb.WriteString("\n\nUsage:\n  yq [flags]\n  yq [command]\n\nExamples:\n\n")
	sb.WriteString(rootExamples)
	sb.WriteString("\n\n\nAvailable Commands:\n")
	sb.WriteString("  completion  Generate the autocompletion script for the specified shell\n")
	sb.WriteString("  eval        (default) Apply the expression to each document in each yaml file in sequence\n")
	sb.WriteString("  eval-all    Loads _all_ yaml documents of _all_ yaml files and runs expression once\n")
	sb.WriteString("  help        Help about any command\n\n")
	sb.WriteString("Flags:\n")
	sb.WriteString(buildFlagsList(true))
	sb.WriteString("\n\nUse \"yq [command] --help\" for more information about a command.\n")
	return sb.String()
}

func evalHelp() string {
	var sb strings.Builder
	sb.WriteString(rootDescHeader)
	sb.WriteString("\n\n## Evaluate Sequence ##\nThis command iterates over each yaml document from each given file, applies the \nexpression and prints the result in sequence.\n\n")
	sb.WriteString("Usage:\n  yq eval [expression] [yaml_file1]... [flags]\n\n")
	sb.WriteString("Aliases:\n  eval, e\n\n")
	sb.WriteString("Examples:\n\n")
	sb.WriteString(evalExamples)
	sb.WriteString("\n\n\nFlags:\n  -h, --help   help for eval\n\nGlobal Flags:\n")
	sb.WriteString(buildFlagsList(false))
	sb.WriteString("\n")
	return sb.String()
}

func evalAllHelp() string {
	var sb strings.Builder
	sb.WriteString(rootDescHeader)
	sb.WriteString("\n\n## Evaluate All ##\nThis command loads _all_ yaml documents of _all_ yaml files and runs expression once\nUseful when you need to run an expression across several yaml documents or files (like merge).\nNote that it consumes more memory than eval.\n\n")
	sb.WriteString("Usage:\n  yq eval-all [expression] [yaml_file1]... [flags]\n\n")
	sb.WriteString("Aliases:\n  eval-all, ea\n\n")
	sb.WriteString("Examples:\n\n")
	sb.WriteString(evalAllExamples)
	sb.WriteString("\n\n\nFlags:\n  -h, --help   help for eval-all\n\nGlobal Flags:\n")
	sb.WriteString(buildFlagsList(false))
	sb.WriteString("\n")
	return sb.String()
}

func completionHelp() string {
	return `Generate the autocompletion script for yq for the specified shell.
See each sub-command's help for details on how to use the generated script.

Usage:
  yq completion [command]

Aliases:
  completion, shell-completion

Available Commands:
  bash        Generate the autocompletion script for bash
  fish        Generate the autocompletion script for fish
  powershell  Generate the autocompletion script for powershell
  zsh         Generate the autocompletion script for zsh

Flags:
  -h, --help   help for completion

Global Flags:
` + buildFlagsList(false) + `

Use "yq completion [command] --help" for more information about a command.
`
}

// ---- parse args ----

type ParsedArgs struct {
	Command    string
	Positional []string
}

func parseArgs(args []string, opts *Options) (*ParsedArgs, error) {
	result := &ParsedArgs{}
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			result.Positional = append(result.Positional, args[i:]...)
			break
		}
		if a == "--help" {
			opts.Help = true
			i++
			continue
		}
		if a == "--version" {
			opts.Version = true
			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			nameVal := a[2:]
			var name, val string
			var hasVal bool
			if eq := strings.IndexByte(nameVal, '='); eq >= 0 {
				name, val, hasVal = nameVal[:eq], nameVal[eq+1:], true
			} else {
				name = nameVal
			}
			fd := findLongFlag(name)
			if fd == nil {
				fmt.Fprintf(os.Stderr, "Error: unknown flag: --%s\n", name)
				fmt.Fprint(os.Stderr, usageShort())
				os.Exit(1)
			}
			if fd.argType != "" && !hasVal {
				i++
				if i >= len(args) {
					fmt.Fprintf(os.Stderr, "Error: flag needs an argument: --%s\n", name)
					os.Exit(1)
				}
				val = args[i]
			}
			if err := fd.setter(val, opts); err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			i++
			continue
		}
		if len(a) > 1 && a[0] == '-' && a != "-" {
			body := a[1:]
			j := 0
			for j < len(body) {
				c := string(body[j])
				if c == "h" {
					opts.Help = true
					j++
					continue
				}
				if c == "V" {
					opts.Version = true
					j++
					continue
				}
				fd := findShortFlag(c)
				if fd == nil {
					fmt.Fprintf(os.Stderr, "Error: unknown shorthand flag: '%s' in -%s\n", c, body)
					os.Exit(1)
				}
				if fd.argType != "" {
					var val string
					rest := body[j+1:]
					if strings.HasPrefix(rest, "=") {
						val = rest[1:]
					} else if rest != "" {
						val = rest
					} else {
						i++
						if i >= len(args) {
							fmt.Fprintf(os.Stderr, "Error: flag needs an argument: '%s'\n", c)
							os.Exit(1)
						}
						val = args[i]
					}
					if err := fd.setter(val, opts); err != nil {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
						os.Exit(1)
					}
					break
				}
				if err := fd.setter("", opts); err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					os.Exit(1)
				}
				j++
			}
			i++
			continue
		}
		if result.Command == "" && len(result.Positional) == 0 {
			switch a {
			case "eval", "e", "eval-all", "ea", "completion", "shell-completion", "help":
				result.Command = a
				i++
				continue
			}
		}
		result.Positional = append(result.Positional, a)
		i++
	}
	return result, nil
}

func usageShort() string {
	return "Usage:\n  yq [flags]\n  yq [command]\n\n" +
		"Examples:\n\n" + rootExamples + "\n\n\n" +
		"Available Commands:\n" +
		"  completion  Generate the autocompletion script for the specified shell\n" +
		"  eval        (default) Apply the expression to each document in each yaml file in sequence\n" +
		"  eval-all    Loads _all_ yaml documents of _all_ yaml files and runs expression once\n" +
		"  help        Help about any command\n\n" +
		"Flags:\n" + buildFlagsList(true) + "\n\n" +
		"Use \"yq [command] --help\" for more information about a command.\n"
}

// ---- main ----

func main() {
	opts := defaultOptions()
	args := os.Args[1:]
	parsed, err := parseArgs(args, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if opts.Version {
		fmt.Println(versionString)
		return
	}
	if opts.Help {
		switch parsed.Command {
		case "eval", "e":
			fmt.Print(evalHelp())
		case "eval-all", "ea":
			fmt.Print(evalAllHelp())
		case "completion", "shell-completion":
			fmt.Print(completionHelp())
		default:
			fmt.Print(rootHelp())
		}
		return
	}
	switch parsed.Command {
	case "help":
		fmt.Print(evalHelp())
		return
	case "completion", "shell-completion":
		runCompletion(parsed.Positional)
		return
	}
	runEval(opts, parsed)
}

func runCompletion(positional []string) {
	if len(positional) == 0 {
		fmt.Fprint(os.Stderr, "Error: accepts 1 arg(s), received 0\n")
		fmt.Fprint(os.Stderr, completionHelp())
		os.Exit(1)
	}
	sh := positional[0]
	switch sh {
	case "bash", "zsh", "fish", "powershell":
		fmt.Printf("# Autocompletion stub for %s\n", sh)
	default:
		fmt.Fprintf(os.Stderr, "Error: unsupported shell %q\n", sh)
		os.Exit(1)
	}
}

func runEval(opts *Options, parsed *ParsedArgs) {
	positional := parsed.Positional
	var expr string
	var files []string
	if opts.Expression != "" {
		expr = opts.Expression
		files = positional
	} else if opts.FromFile != "" {
		data, err := os.ReadFile(opts.FromFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		expr = string(data)
		files = positional
	} else if len(positional) > 0 {
		first := positional[0]
		if looksLikeExpression(first) {
			expr = first
			files = positional[1:]
		} else {
			expr = "."
			files = positional
		}
	} else {
		expr = "."
	}
	outFmt := normalizeFmt(opts.OutputFormat)
	if outFmt == "auto" {
		outFmt = "yaml"
	}
	inFmt := normalizeFmt(opts.InputFormat)

	var inputs []rawDoc
	if opts.NullInput {
		inputs = []rawDoc{{fmt: "null"}}
	} else if len(files) == 0 {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		actualFmt := inFmt
		if actualFmt == "auto" {
			actualFmt = detectFormat(data)
		}
		inputs = splitDocs(data, actualFmt)
	} else {
		for _, fn := range files {
			var data []byte
			var err error
			if fn == "-" {
				data, err = io.ReadAll(os.Stdin)
			} else {
				data, err = os.ReadFile(fn)
			}
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			actualFmt := inFmt
			if actualFmt == "auto" {
				actualFmt = guessFormat(fn, data)
			}
			docs := splitDocs(data, actualFmt)
			inputs = append(inputs, docs...)
		}
	}

	writer := os.Stdout
	for idx, doc := range inputs {
		val, err := evaluate(expr, doc, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		if idx > 0 && !opts.NoDoc && outFmt == "yaml" {
			fmt.Fprintln(writer, "---")
		}
		if err := writeValue(writer, val, outFmt, opts); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
}

func looksLikeExpression(s string) bool {
	if _, err := os.Stat(s); err == nil {
		return false
	}
	if s == "-" {
		return false
	}
	if strings.ContainsAny(s, ".|=()[]$*") || strings.HasPrefix(s, "\"") {
		return true
	}
	return false
}

func normalizeFmt(s string) string {
	switch s {
	case "a", "auto":
		return "auto"
	case "y", "yaml", "yml":
		return "yaml"
	case "ky", "kyaml":
		return "kyaml"
	case "j", "json":
		return "json"
	case "p", "props", "properties":
		return "props"
	case "c", "csv":
		return "csv"
	case "t", "tsv":
		return "tsv"
	case "x", "xml":
		return "xml"
	case "base64":
		return "base64"
	case "uri":
		return "uri"
	case "toml":
		return "toml"
	case "h", "hcl":
		return "hcl"
	case "s", "shell":
		return "shell"
	case "l", "lua":
		return "lua"
	case "i", "ini":
		return "ini"
	case "":
		return "auto"
	}
	return s
}

func guessFormat(fn string, data []byte) string {
	low := strings.ToLower(fn)
	switch {
	case strings.HasSuffix(low, ".json"):
		return "json"
	case strings.HasSuffix(low, ".xml"):
		return "xml"
	case strings.HasSuffix(low, ".properties"):
		return "props"
	case strings.HasSuffix(low, ".csv"):
		return "csv"
	case strings.HasSuffix(low, ".tsv"):
		return "tsv"
	case strings.HasSuffix(low, ".toml"):
		return "toml"
	case strings.HasSuffix(low, ".ini"):
		return "ini"
	case strings.HasSuffix(low, ".lua"):
		return "lua"
	case strings.HasSuffix(low, ".yaml"), strings.HasSuffix(low, ".yml"):
		return "yaml"
	}
	return detectFormat(data)
}

func detectFormat(data []byte) string {
	trimmed := strings.TrimSpace(string(data))
	if strings.HasPrefix(trimmed, "{") || strings.HasPrefix(trimmed, "[") {
		return "json"
	}
	return "yaml"
}
