// ---- help rendering ----

// Render a single flag line with description starting at column `descCol`.
func renderFlagLine(fd flagDef, descCol int) string {
	var nameSB strings.Builder
	if fd.short != "" {
		nameSB.WriteString("  -")
		nameSB.WriteString(fd.short)
		nameSB.WriteString(", --")
	} else {
		nameSB.WriteString("      --")
	}
	nameSB.WriteString(fd.long)
	if fd.argType != "" {
		nameSB.WriteByte(' ')
		nameSB.WriteString(fd.argType)
	}
	name := nameSB.String()
	pad := descCol - len(name)
	if pad < 3 {
		pad = 3
	}
	return name + strings.Repeat(" ", pad) + fd.desc
}

// buildFlagsList returns the formatted flag block, including optional help/version lines at proper positions.
func buildFlagsList(includeHelpVersion bool) string {
	type entry struct{ fd flagDef }
	// Create entries with alphabetical ordering by long name
	var entries []flagDef
	entries = append(entries, allFlags...)
	if includeHelpVersion {
		entries = append(entries, flagDef{short: "h", long: "help", desc: "help for yq"})
		entries = append(entries, flagDef{short: "V", long: "version", desc: "Print version information and quit"})
	}
	// Sort by long name (stable alphabetical)
	sortFlagsByLong(entries)
	descCol := 42
	var lines []string
	for _, fd := range entries {
		lines = append(lines, renderFlagLine(fd, descCol))
	}
	return strings.Join(lines, "\n")
}

func sortFlagsByLong(list []flagDef) {
	// Insertion sort (small list)
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && list[j].long < list[j-1].long; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
}

